// Only the rules of Mantine's styles.css that the site renders: all of it is
// render-blocking on every page. Generated by
// `node scripts/mantine-css.mjs --write`, which says how they are found.
import '@/theme/mantine.css';
// !! The order of these imports is important !!
import '@gfazioli/mantine-text-animate/styles.css';
import '@gfazioli/mantine-scene/styles.css';
// Mantine theme overrides and the --vic-* tokens (body background, springs)
import '@/theme/global.css';

import { EB_Garamond } from 'next/font/google';
import { Analytics } from '@vercel/analytics/react';
import { Layout } from 'nextra-theme-docs';
import { Head } from 'nextra/components';
import { getPageMap } from 'nextra/page-map';
import { ColorSchemeScript, mantineHtmlProps, MantineProvider } from '@mantine/core';
// !! End of important imports !!

import { MantineFooter, MenuBarHeader } from '@/components';
import { NewsletterModal } from '@/components/NewsletterSignup/NewsletterModal';
import { WebsiteJsonLd } from '@/components/StructuredData/StructuredData';
import config from '@/config';
import { theme } from '../theme';

import './global.css';

export const metadata = config.metadata;

/**
 * The display face, and the one deliberate borrowing on this site.
 *
 * The reference is Apple's *Think Different* campaign, which was set in **Apple
 * Garamond** — Apple's own cut of ITC Garamond, condensed to about 80%, used
 * from 1984 to 2002 and never licensed to anybody else. It is not available to
 * us and the copies that circulate share its provenance, so this is EB Garamond
 * (SIL Open Font License): the same Garamond lineage, legitimately.
 *
 * The hero line takes a slight horizontal scale in CSS, which is where Apple
 * Garamond's condensed proportion actually lives — see `.display-hero`.
 *
 * TWO CALLS, AND ONLY THE UPRIGHT ONE PRELOADED. One call with both styles
 * preloaded the italic's file on every page, and the italic is drawn only by
 * the home page's closing line, far below the fold. Chrome's render-blocking
 * fonts hold the first paint for a preloaded font the page is loading, and a
 * font no text above the fold asks for never settles: the paint waited for a
 * timeout instead, about 1.1 s after the preload turned render-blocking.
 * Measured 2026-10-29 in Lighthouse traces of /docs/privacy, main and branch
 * alike: the upright file landed at 1.83 s and the first paint at 2.68 s, in
 * 2 of 3 runs on main and 1 of 3 on the branch; the paint lands at 1.69 s when
 * it wins the race. Both calls name the same variable, so `.display` is one
 * family with an upright and an italic face, as lancetta.app's layout does it;
 * the italic is fetched when the closing line asks for it.
 */
const display = EB_Garamond({
  subsets: ['latin'],
  weight: ['400', '500', '600'],
  style: 'normal',
  variable: '--font-display',
  display: 'swap',
});

const displayItalic = EB_Garamond({
  subsets: ['latin'],
  weight: ['400'],
  style: 'italic',
  variable: '--font-display',
  display: 'swap',
  preload: false,
});

export default async function RootLayout({ children }: { children: React.ReactNode }) {
  const pageMap = await getPageMap();
  const { nextraLayout, head } = config;

  return (
    // `data-scroll-behavior`: the stylesheet makes <html> scroll smoothly (for
    // the page's own anchors), and without this attribute Next 16 keeps that
    // on a route change too. lancetta.app, coming home from a docs page,
    // mounted near the bottom and scrolled to the top for 1.5 s, past every
    // section, firing each one-shot reveal out of sight. With it, Next jumps
    // before any effect reads the scroll.
    <html
      lang="en"
      dir="ltr"
      data-scroll-behavior="smooth"
      className={`${display.variable} ${displayItalic.variable}`}
      {...mantineHtmlProps}
    >
      <Head>
        {/*
          Forced, not defaulted: the site is dark only, with no switch (user,
          2026-09-23: keep the dark palette it has, drop the toggle).
          `forceColorScheme` makes the pre-hydration script write `dark`
          whatever is in local storage, so a visitor who chose light with the
          old switch is not left on a scheme nothing here is kept for.
        */}
        <ColorSchemeScript nonce={head.mantine.nonce} forceColorScheme="dark" />
        <link rel="icon" type="image/png" sizes="32x32" href="/favicon-32x32.png" />
        <link rel="icon" type="image/png" sizes="16x16" href="/favicon-16x16.png" />
        <link rel="shortcut icon" href="/favicon.ico" />
        <link rel="apple-touch-icon" sizes="180x180" href="/apple-touch-icon.png" />
        {/*
          No manual viewport meta: Next emits `width=device-width,
          initial-scale=1` by default. The previous override added
          `user-scalable=no`, which blocks pinch-zoom — an accessibility
          regression (and a Lighthouse flag). Let the default stand so
          users can zoom.
        */}
      </Head>
      <body>
        <MantineProvider theme={theme} forceColorScheme="dark">
          {/*
            `navbar` is OUR bar, on every page, as on lancetta.app. Nextra
            renders whatever is in this slot in place of its own <Navbar>, so
            the default header is gone rather than hidden, which is why
            `MenuBarHeader` carries the search and the hamburger that bar did.
          */}
          <Layout
            navbar={<MenuBarHeader />}
            pageMap={pageMap}
            docsRepositoryBase={nextraLayout.docsRepositoryBase}
            footer={<MantineFooter year={new Date().getFullYear()} />}
            sidebar={nextraLayout.sidebar}
            // Nextra's dark theme, forced, with no switch in its sidebar.
            darkMode={false}
            nextThemes={{ defaultTheme: 'dark', forcedTheme: 'dark' }}
          >
            {children}
          </Layout>
          <NewsletterModal />
        </MantineProvider>
        <WebsiteJsonLd />
        <Analytics />
      </body>
    </html>
  );
}
